-- 0.16.0, T179 PR 6: the indexes of postgres/0067_refusals.sql, for the same reads. SQLite writes no such record (its key writes and adds keep today's path, which logs their refusals in 0.14's log), so they hold none; the reads that would use them run the same.
CREATE INDEX `log_changes_refused_write_idx` ON `log_changes` (`at`,`number`) WHERE (instr("log_changes"."payload", '{"code":"') = 1 AND instr("log_changes"."payload", '"op":"write.refused"') > 0);--> statement-breakpoint
CREATE INDEX `log_changes_refused_write_actor_idx` ON `log_changes` (`actor`,`at`,`number`) WHERE (instr("log_changes"."payload", '{"code":"') = 1 AND instr("log_changes"."payload", '"op":"write.refused"') > 0);--> statement-breakpoint
CREATE INDEX `log_changes_refused_write_environment_idx` ON `log_changes` (json_extract("payload", '$.environmentId'),`at`,`number`) WHERE (instr("log_changes"."payload", '{"code":"') = 1 AND instr("log_changes"."payload", '"op":"write.refused"') > 0);--> statement-breakpoint
CREATE INDEX `log_changes_refused_write_actor_environment_idx` ON `log_changes` (`actor`,json_extract("payload", '$.environmentId'),`at`,`number`) WHERE (instr("log_changes"."payload", '{"code":"') = 1 AND instr("log_changes"."payload", '"op":"write.refused"') > 0);--> statement-breakpoint
CREATE INDEX `log_changes_refused_add_idx` ON `log_changes` (`at`,`number`) WHERE (instr("log_changes"."payload", '{"code":"') = 1 AND instr("log_changes"."payload", '"op":"add.refused"') > 0);--> statement-breakpoint
CREATE INDEX `log_changes_refused_add_actor_idx` ON `log_changes` (`actor`,`at`,`number`) WHERE (instr("log_changes"."payload", '{"code":"') = 1 AND instr("log_changes"."payload", '"op":"add.refused"') > 0);
